MATCH (c1:Character {name: 'Wipeout'}), (c2:Character {name: 'Chris Bradley'})
RETURN c1.gender AS gender1, c2.gender AS gender2,
       CASE WHEN c1.gender = c2.gender THEN true ELSE false END AS sameGender;

MATCH (c:Character)-[:bornIn]->(loc:Location)
WHERE EXISTS { MATCH (c)-[:diedIn]->(loc) }
RETURN DISTINCT c.creator AS creator

MATCH (c:Character)
WHERE EXISTS { MATCH (c)-[:hasFather]->(:Character {name: 'Corlys Velaryon'}) }
   OR EXISTS { MATCH (c)-[:hasSpouse]->(:Character {name: 'Daemon Targaryen'}) }
RETURN count(DISTINCT c) AS characterCount

MATCH (c:Character)-[:memberOf]->(org:Organization)
WHERE ANY(o IN c.occupation WHERE o = 'spy')
  AND EXISTS {
    MATCH (org)-[rel]->(loc:Location {name: 'Kirky Hassary'})
  }
RETURN c.name AS name

MATCH (c:Character)
WHERE (
      EXISTS { MATCH (:Character {name: 'Liu Fu'})-[:killedBy]->(c) }
   OR EXISTS { MATCH (c)-[:hasSpouse]->(:Character {name: 'Lady Liu'}) }
)
RETURN count(DISTINCT c) AS totalCharacters;
